// Provider (generator)
// ---------------------------------------------------------------------------------------

export interface ToolSpec {
  name: string;
  description: string;
  /** JSON Schema object; strict on Anthropic (additionalProperties false, required listed). */
  inputSchema: JsonObject;
}
export interface ToolCall {
  name: string;
  input: Json;
  rawJson: string;
}
export type ToolChoice = 'auto' | 'required' | { name: string };

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
}
/** docs/LLM-JEV-DESIGN.md §4.12 verbatim. */
export type ReasoningEffort = 'low' | 'medium';
/**
 * docs/LLM-JEV-DESIGN.md §4.12 verbatim: `{enabled: false}` turns thinking off where the model allows it; `{effort}` asks
 * for it at a level (on OpenRouter `effort` alone implies enabled). Providers send it as given, never rewritten; absent =
 * the model's default. Discriminate on the member present (`'effort' in r`, `'maxTokens' in r`), never on a truthy read.
 *
 * `{maxTokens}` (additive, 2026-09-21) is OpenRouter's `reasoning: {max_tokens: N}` — a thinking budget in tokens, the
 * alternative to `effort` (the two are mutually exclusive on the wire). A pass-through for a later tuning of GLM's fat
 * latency tail (`experiments/results/llm-jev-headtohead.md` §6: valid p90 25.6 s at effort `low`): whether the GLM endpoint
 * honours a token budget or OpenRouter folds it into an effort level is NOT verified live — nothing in the tree sends it yet.
 */
export type GenerateReasoning = { enabled: false } | { effort: ReasoningEffort } | { maxTokens: number };
/** docs/LLM-JEV-DESIGN.md §4.12 verbatim: OpenRouter routes only to endpoints that support every parameter sent (tools, seed, …). */
export interface GenerateProviderPrefs {
  requireParameters: boolean;
}
export interface GenerateRequest {
  system: string;
  messages: ChatMessage[];
  maxTokens: number;
  /** null = do not send the parameter (Claude Sonnet 5 rejects non-default values). */
  temperature: number | null;
  tools?: ToolSpec[];
  toolChoice?: ToolChoice;
  /** docs/LLM-JEV-DESIGN.md §4.6: per-sample seed (OpenRouter `seed`); providers without it ignore it */
  seed?: number;
  /** docs/LLM-JEV-DESIGN.md §4.12: reasoning control (OpenRouter `reasoning`); providers without it ignore it */
  reasoning?: GenerateReasoning;
  /** docs/LLM-JEV-DESIGN.md §4.12: OpenRouter routing preferences (`provider.require_parameters`); providers without it ignore it */
  providerPrefs?: GenerateProviderPrefs;
}
export interface GenerateResult {
  /** concatenated text blocks (streamed via onDelta) */
  text: string;
  toolCalls: ToolCall[];
  usage: TokenUsage;
  model: string;
  stopReason: string;
  latencyMs: number;
  /** docs/LLM-JEV-DESIGN.md §4.8: the provider's generation id (OpenRouter chunk `id` `gen-…`, Anthropic `message.id`), for post-hoc cost reconciliation */
  generationId?: string;
  /** docs/LLM-JEV-DESIGN.md §4.12: OpenRouter's response `provider` field — the upstream that served the request (bills at its own rate, §8); absent on Anthropic */
  servedProvider?: string;
  /**
   * true when at least one attempt of this call was answered HTTP 429 before the result arrived (the retry chain recovered).
   * A fact for the controller — a round whose samples all needed a 429 retry is running into a rate limit even when it
   * succeeded — never a reason to change the result. Absent (not false) otherwise.
   */
  rateLimited?: true;
}
/** TUI-DESIGN §15 item 5: why a client is about to sleep before a retry; message = redacted <= 200-char hint, never a body */
export interface RetryCause {
  kind: 'http' | 'network' | 'timeout' | 'invalid' | 'stream';
  status: number | null;
  code: string | null;
  message: string;
}
/** TUI-DESIGN §15 item 5 */
export interface RetryInfo {
  attempt: number;
  maxAttempts: number;
  waitMs: number;
  retryAfter: boolean;
  cause: RetryCause;
}
/**
 * docs/LLM-JEV-DESIGN.md §4.8: what the provider knows about a stream when its signal fired, handed to
 * `GenerateOptions.onCancelled` right before `signal.reason` is rethrown (an aborted sample still yields no `GenerateResult`).
 *
 * Facts only — the estimate is the ENGINE'S (`Engine.recordCancelledSample()`: input = a sibling sample's `prompt_tokens`,
 * output = `toolChars` / 4, priced at the served rate, `estimated: true`). This record carries what the engine cannot recover
 * on its own: the ids for the post-hoc lookup and the streamed sizes. It is NOT delivered when the abort lands before the
 * response headers (the prompt may still be billed) — the engine estimates alone then. Precedence: the engine takes
 * `generationId` / `servedProvider` / `toolChars` / `usage` from here when the callback fired, else uses its own estimate.
 */
export interface CancelledGeneration {
  generationId?: string;
  servedProvider?: string;
  model?: string;
  /** text streamed so far */
  text: string;
  /** tool-argument characters streamed so far (§4.8: the estimate's output side is `toolChars / 4`) */
  toolChars: number;
  /** thinking characters streamed so far (`delta.reasoning`; billed as output too); 0 on Anthropic (thinking is never requested) */
  reasoningChars: number;
  /** present only when the accounting frame had already arrived (the abort landed between it and the end of the stream): read and priced like a completed call, not estimated */
  usage?: TokenUsage;
  /**
   * true when the sample ended rate-limited: every attempt of the retry chain was answered HTTP 429 (the chain gave up), or
   * the signal aborted the sample while it was waiting out a 429 backoff. Delivered with zero streamed sizes and no ids when
   * no stream ever opened (nothing was served, nothing is billed — the engine records the sample with `stopReason`
   * 'rate_limited' and zero usage rather than an estimate); the source classifies a round whose samples all ended so as
   * `rate_limited`, not exhausted, so the controller may fire it again next step. Absent (not false) otherwise.
   */
  rateLimited?: true;
}
export interface GenerateOptions {
  signal: AbortSignal;
  onDelta?: (text: string) => void;
  /** streamed tool-call argument fragments (for the TUI's "streaming action… N chars") */
  onToolDelta?: (fragment: string) => void;
  /** TUI-DESIGN §15 item 5: called before each retry sleep */
  onRetry?: (info: RetryInfo) => void;
  /** TUI-DESIGN §15 item 5: a GETTER read before each sleep (one AbortController per sleep); clients: `await sleep(waitMs, signal, opts.wake?.())` */
  wake?: () => AbortSignal | undefined;
  /** docs/LLM-JEV-DESIGN.md §4.8: the sample index of a parallel round (llm-jev); absent for the one-sample propose stage */
  sample?: number;
  /**
   * docs/LLM-JEV-DESIGN.md §4.8: called at most once, after the stream's abort and before `signal.reason` is rethrown, when the
   * signal aborted a stream whose response headers had arrived — or, with `rateLimited: true`, when the call ended rate-limited
   * without a stream (every retry answered 429, or the abort landed during a 429 backoff; `CancelledGeneration.rateLimited`).
   * Runs outside the retry loop: a throwing callback is a harness bug and propagates as a typed 'internal' error in place of
   * the abort reason, exactly like a throwing `onDelta`.
   */
  onCancelled?: (partial: CancelledGeneration) => void;
}
export type ProviderName = 'anthropic' | 'openrouter' | 'mock';
export interface Provider {
  readonly name: ProviderName;
  readonly model: string;
  generate(req: GenerateRequest, opts: GenerateOptions): Promise<GenerateResult>;
}

