// TUI-DESIGN §15 item 17: 'ignored:launch' = a file key for a launch setting (§16)
export type ConfigSource = 'flag' | 'env' | `dotenv:${string}` | `file:${string}` | 'default' | 'run.json' | 'wizard' | 'derived' | 'session:/budget' | 'ignored:launch';
/** TUI-DESIGN §15 item 17 */
export type SecretSettingName = 'generator.apiKey' | 'decider.apiKey';

export interface Resolved<T> {
  value: T;
  source: ConfigSource;
}

export interface GeneratorConfig {
  provider: 'anthropic' | 'openrouter';
  model: string;
  apiKey: string;
  baseUrl: string;
  temperature: number | null;
  maxTokens: number;
  /** USD per million tokens, used when the API returns no cost; `contextTokens` is contract 1.4 (§8.2, §14 Q4): the model's context window, absent → DEFAULT_GENERATOR_CONTEXT_TOKENS */
  pricing: { inputPerM: number; outputPerM: number; cacheReadPerM: number; cacheWritePerM: number; contextTokens?: number };
  /**
   * TUI-DESIGN §15 item 17: OPTIONAL: validateGenerator always sets it; resolveConfig / validate.ts treat absent as false.
   * §9.5: absent ⇒ a null OpenRouter `usage.cost` yields `costUsd` NaN (`budget:unpriced`, stop `error unpriced_usage` unless
   * --allow-unpriced), never a table price — a GeneratorConfig built without validateGenerator must set it to get the table.
   */
  priced?: boolean;
}

// TUI-DESIGN-2 §6 item 4 / §2.2: the two Jev endpoints (jev/providers.ts holds the table) and how the provider was chosen (§2.3 rules 1–2e)
export type JevProvider = 'typesafe' | 'openrouter';
export type JevProviderSource = 'flag' | 'env' | `dotenv:${string}` | `file:${string}` | 'auto:base-url' | 'auto:typesafe-key' | 'auto:openrouter-key' | 'default';
/** TUI-DESIGN-2 §6 item 4: three REQUIRED fields since contract 1.2; the only production constructor is config/validate.ts `validateDecider` */
export interface DeciderConfig {
  provider: JevProvider;
  baseUrl: string;
  apiKey: string;
  /** configured id, verbatim */
  model: string;
  /** provider-aware (§2.5): openrouter — the normalised id ends in -YYYYMMDD; typesafe — `jev-<major>.<minor>.<patch>` */
  pinned: boolean;
  /** the provider table's rates; the client prices a response from them when the wire carries no `usage.cost` (§2.4) */
  pricing: { inputUsdPerToken: number; outputUsdPerToken: number };
  providerSource: JevProviderSource;
}

export interface ResolvedConfig {
  /** every setting with its source; secrets appear only as fingerprints in record() */
  readonly entries: ReadonlyMap<string, Resolved<string>>;
  /** TUI-DESIGN-2 §6 item 9 / §1.2: the `mode` setting (flag > JEVCODE_MODE > dotenv > file > DEFAULT_MODE); the mode-keyed spend caps read it */
  readonly mode: EngineMode;
  /** validates the generator section on first call; ConfigError names setting and sources */
  generator(): GeneratorConfig;
  /** validates the decider section on first call */
  decider(): DeciderConfig;
  limits(): RunLimits;
  workspace: string;
  runsDir: string;
  openAssistPath: string | null;
  configFile: string | null;
  /** dotenv files that were actually read */
  dotenvFiles: readonly string[];
  sandbox: SandboxProfile;
  noNetwork: boolean;
  plain: boolean;
  /** secret file paths (dotenvs, config file) for the sandbox read-deny list and SecretPathError */
  secretPaths: readonly string[];
  /** redaction built from the SecretSet (§8.4) */
  redact: (s: string) => string;
  redactJson: (v: Json) => Json;
  /** masked table for run.json and `jevcode config` */
  record(): Record<string, ConfigRecordValue>;
  // TUI-DESIGN §15 item 17 — required since contract 1.1 wave 1 (config/resolve.ts implements them; O6).
  /** non-throwing; skips generator.apiKey for jev-only and --mock* */
  missingSecrets(mode: EngineMode): readonly SecretSettingName[];
  /** session settings through the full chain; the launch members are copied from the argument, never re-resolved */
  ui(launch: LaunchSettings): UiConfig;
  /** 'none' -> +Infinity */
  sessionSpendCap(mode: EngineMode): { value: number; source: ConfigSource; derived: boolean };
  /**
   * TUI-DESIGN-4 §8 (the round-4 config rows): the relaxed-context policy from the config chain
   * (docs/COORDINATION-DESIGN.md §8), with ONLY the members the user set — the engine keeps `src/core/limits.ts`'s
   * defaults for the rest. Optional so no existing `ResolvedConfig` fake breaks; `config/resolve.ts` always sets it.
   */
  context?(): ContextPolicyOptions;
  /** delegate to the redactor */
  addSecret(name: string, value: string): boolean;
  dropSecret(name: string): boolean;
  /** resolved XDG + legacy jevcode dirs (§12.7) */
  readonly configDirs: readonly string[];
}

